@push('scripts')<script>(()=>{const f=[...document.querySelectorAll('.score-input')],w=[.4,.25,.15,.2],o=document.getElementById('overall');function c(){o.textContent=f.reduce((s,e,i)=>s+(Number(e.value)||0)*w[i],0).toFixed(2)+' / 100'}f.forEach(e=>e.addEventListener('input',c));c()})();</script>@endpush
